import { test, expect } from 'libretto/test'

test.describe("Controls", () => {
  test("nap mode survives a reload and can be switched back off", async ({ page }) => {
    await test.step("Steps 1: Open the live page", async () => {
      await page.goto('/');
    })
    await test.step("Steps 2: Turn on the \"Nap mode\" switch; the hint changes to \"Nap mode is on\"", async () => {
      await page.getByRole('checkbox', { name: 'Nap mode' }).check({ force: true });
      await expect(page.getByText('Nap mode is on')).toBeVisible();
    })
    await test.step("Steps 3: Reload the page; the \"Nap mode\" switch is still on", async () => {
      await page.reload();
      await expect(page.getByRole('checkbox', { name: 'Nap mode' })).toBeChecked();
    })
    await test.step("Steps 4: Turn off the \"Nap mode\" switch; the hint changes to \"Nap mode is off\"", async () => {
      await page.getByRole('checkbox', { name: 'Nap mode' }).uncheck({ force: true });
      await expect(page.getByText('Nap mode is off')).toBeVisible();
    })
    await test.step("Steps 5: Reload the page", async () => {
      await page.reload();
    })
    await test.step("Expect 1: The \"Nap mode\" switch is off", async () => {
      await expect(page.getByRole('checkbox', { name: 'Nap mode' })).not.toBeChecked();
    })
    await test.step("Expect 2: The \"Armed\" switch is on", async () => {
      await expect(page.getByRole('checkbox', { name: 'Armed' })).toBeChecked();
    })
  })

  test("set reference saves the current frame", async ({ page }) => {
    await test.step("Steps 1: Open the live page", async () => {
      await page.goto('/');
    })
    await test.step("Steps 2: Click \"Set reference\"", async () => {
      await page.getByRole('button', { name: 'Set reference', exact: true }).click();
    })
    await test.step("Expect 1: The note \"Reference saved.\" appears", async () => {
      await expect(page.getByText('Reference saved.')).toBeVisible();
    })
  })
})
